// Turns each row of the competitor list into a price check.
// A row has either a product_url (the competitor's product page), or a competitor_url plus
// a SKU, UPC, MPN, or product name to search that site for.
const rows = $('Get Competitor List').all().map((i) => i.json);

const text = (v) => String(v ?? '').trim();
// (URL() isn't available in n8n's Code node, so URLs are read with patterns)
const hostOf = (url) => (url.match(/^https?:\/\/([^/?#:\s]+)/i)?.[1] ?? '').toLowerCase();
const domainOf = (value) => text(value).toLowerCase()
  .replace(/^https?:\/\//, '').replace(/[/?#:].*$/, '').replace(/^www\./, '');
// Drops tracking parameters and the #fragment, so the same page always gets the same key
const cleanUrl = (url) => {
  const [base] = url.split('#');
  const [path, query = ''] = base.split('?');
  const kept = query.split('&').filter((p) => p && !/^(utm_[a-z]+|gclid|gbraid|wbraid|fbclid|msclkid|srsltid|_ga|mc_cid|mc_eid)=/i.test(p));
  const host = hostOf(path);
  const rest = path.replace(/^https?:\/\/[^/?#]+/i, '').replace(/(.)\/$/, '$1');
  return `https://${host}${rest}${kept.length ? `?${kept.join('&')}` : ''}`;
};
// Sheets drops the leading zero of a 12-digit UPC stored as a number
const cleanUpc = (v) => {
  const s = text(v).replace(/\s|-/g, '');
  return /^\d{11}$/.test(s) ? `0${s}` : s;
};

const out = [];
for (const row of rows) {
  const ids = { sku: text(row.sku), upc: cleanUpc(row.upc), mpn: text(row.mpn) };
  const productName = text(row.product_name);
  const brand = text(row.brand);
  const productUrl = text(row.product_url).match(/https?:\/\/\S+/i)?.[0] ?? '';
  const siteInput = text(row.competitor_url);
  if (!productUrl && !siteInput && !ids.sku && !ids.upc && !ids.mpn && !productName) continue;

  const savedUrl = text(row.matched_url).match(/^https?:\/\/\S+/i)?.[0] ?? '';
  const domain = domainOf(productUrl || savedUrl || siteInput);
  const base = {
    list_row: row.row_number,
    competitor: text(row.competitor) || domain,
    domain,
    product_name: productName,
    brand,
    ...ids,
  };
  const add = (json) => out.push({ json: { ...base, ...json }, pairedItem: { item: 0 } });
  const fail = (code, error) => add({ lookup: 'error', ok: false, code, error });

  // A product page you gave, or one matched on an earlier run: price it directly
  if (productUrl || savedUrl) {
    const url = cleanUrl(productUrl || savedUrl);
    add({ lookup: 'url', found_by: productUrl ? 'product url' : 'search', productUrl: url, product_key: url });
    continue;
  }

  if (!/^[a-z0-9-]+(\.[a-z0-9-]+)+$/.test(domain)) {
    fail('invalid_request', 'Add the competitor\'s website in competitor_url (for example bestbuy.com), or the product page in product_url.');
    continue;
  }

  // Search the competitor's site for the most specific identifier the row has
  const identifier = ids.mpn || ids.upc || ids.sku || productName;
  if (!identifier) {
    fail('invalid_request', 'Add a SKU, UPC, MPN, or product name to search the competitor\'s site for, or the product page in product_url.');
    continue;
  }
  add({
    lookup: 'search',
    found_by: 'search',
    searched_for: identifier,
    searchQuery: `site:${domain} ${identifier}`,
  });
}

return out;

// Takes the top pages on the competitor's site from Pumice Universal Search for each row.
// Each one is scraped and checked with Pumice product matching before it is used.
const MAX_CANDIDATES = 3;
const out = [];

const hostOf = (url) => (String(url).match(/^https?:\/\/([^/?#:\s]+)/i)?.[1] ?? '').toLowerCase();
const cleanUrl = (url) => {
  const [base] = String(url).split('#');
  const [path, query = ''] = base.split('?');
  const kept = query.split('&').filter((p) => p && !/^(utm_[a-z]+|gclid|gbraid|wbraid|fbclid|msclkid|srsltid|_ga|mc_cid|mc_eid)=/i.test(p));
  const host = hostOf(path);
  const rest = path.replace(/^https?:\/\/[^/?#]+/i, '').replace(/(.)\/$/, '$1');
  return `https://${host}${rest}${kept.length ? `?${kept.join('&')}` : ''}`;
};

$input.all().forEach((item, i) => {
  let request;
  try {
    request = $('How to Find the Product?').itemMatching(i).json;
  } catch (e) {
    request = $('How to Find the Product?').all(0)[i].json;
  }
  const res = item.json;

  // The response shape can vary, so check the common containers
  let list = res.results ?? res.data ?? res.items ?? res.pages ?? res.urls ?? res.organic ?? [];
  if (list && !Array.isArray(list) && Array.isArray(list.results)) list = list.results;
  if (!Array.isArray(list)) list = [];

  const seen = new Set();
  const pages = [];
  for (const r of list) {
    const url = typeof r === 'string' ? r : (r?.url || r?.link || r?.source_url || r?.page_url || '');
    const host = hostOf(url);
    // Only pages on the competitor's site (any subdomain), and not its home page or search results
    const onSite = host === request.domain || host.endsWith(`.${request.domain}`);
    const isHome = /^https?:\/\/[^/?#]+\/?$/i.test(url);
    const isSearch = /\/search|searchpage|[?&](q|query|st|k|search|searchTerm)=/i.test(url);
    if (!onSite || isHome || isSearch) continue;
    const clean = cleanUrl(url);
    if (seen.has(clean)) continue;
    seen.add(clean);
    pages.push(clean);
    if (pages.length >= MAX_CANDIDATES) break;
  }

  if (!pages.length) {
    const reason = typeof res.error === 'string' ? res.error : res.error?.message;
    out.push({
      json: {
        ...request,
        lookup: 'error',
        ok: false,
        code: reason ? 'scrape_failed' : 'not_found',
        error: reason
          ? `Pumice Universal Search failed (${reason}). It will be tried again on the next run.`
          : `No pages on ${request.domain} were found for "${request.searched_for}". Try another identifier, or add the product page in product_url.`,
      },
      pairedItem: { item: i },
    });
    return;
  }

  pages.forEach((url, rank) => {
    out.push({
      json: { ...request, productUrl: url, product_key: url, candidate_rank: rank + 1, candidate_count: pages.length },
      pairedItem: { item: i },
    });
  });
});

return out;

