// Builds the two product records for Pumice product matching:
// product_1 is the row you entered, product_2 is the page Smart Scrape just read.
const candidate = $('Pick Candidates').item.json;
const res = $input.item.json;

let d = res.data ?? res.result ?? res.output ?? res.extracted ?? res;
if (typeof d === 'string') {
  try { d = JSON.parse(d); } catch (e) { d = {}; }
}
if (Array.isArray(d)) d = d[0] ?? {};
d = d && typeof d === 'object' ? d : {};
const text = (v) => (Array.isArray(v) ? v.join(' ') : String(v ?? '')).trim();
const compact = (o) => Object.fromEntries(Object.entries(o).filter(([, v]) => v));

// The SKU is only compared when the row has no title, UPC, or MPN, because SKUs are often store-specific
const useSku = !candidate.product_name && !candidate.upc && !candidate.mpn;
const product1 = compact({
  title: candidate.product_name,
  brand: candidate.brand,
  upc: candidate.upc,
  mpn: candidate.mpn,
  sku: useSku ? candidate.sku : '',
});
const product2 = compact({
  title: text(d.title ?? d.product_title ?? d.name),
  brand: text(d.brand),
  upc: text(d.upc ?? d.gtin ?? d.ean),
  mpn: text(d.mpn ?? d.model_number ?? d.model),
  sku: text(d.sku),
  description: text(d.description ?? d.features).slice(0, 1500),
});

return {
  json: {
    ...candidate,
    scraped_title: product2.title ?? '',
    // The product matching endpoint expects each product as a JSON string
    product_1: JSON.stringify(product1),
    product_2: JSON.stringify(product2),
  },
};

// Reads Pumice product matching's answer for one candidate: yes, no, or error.
const candidate = $('Prepare Match').item.json;
const res = $input.item.json;
const answer = String(res.answer ?? res.data?.answer ?? res.result?.answer ?? '').trim().toLowerCase();
const reason = typeof res.error === 'string' ? res.error : res.error?.message;

const { product_1, product_2, ...rest } = candidate;
return {
  json: {
    ...rest,
    match: answer === 'yes' ? 'yes' : answer === 'no' ? 'no' : 'error',
    match_error: answer === 'yes' || answer === 'no' ? '' : (reason || 'No answer from product matching'),
  },
};

// Picks, for each row, the highest-ranked search result that product matching confirmed
// is the same product. Rows where no result matched get an error instead.
const rows = new Map();
const out = [];

$input.all().forEach((item, i) => {
  const r = item.json;
  if (r.ok === false) {
    out.push({ json: r, pairedItem: { item: i } });
    return;
  }
  if (!rows.has(r.list_row)) rows.set(r.list_row, []);
  rows.get(r.list_row).push({ r, i });
});

for (const list of rows.values()) {
  list.sort((a, b) => a.r.candidate_rank - b.r.candidate_rank);
  const hit = list.find(({ r }) => r.match === 'yes');
  const { r: first, i } = hit ?? list[0];
  const { candidate_rank, candidate_count, match, match_error, scraped_title, ...base } = first;

  if (hit) {
    out.push({ json: { ...base, lookup: 'url' }, pairedItem: { item: i } });
    continue;
  }

  const allFailed = list.every(({ r }) => r.match === 'error');
  const checked = list
    .map(({ r }) => (r.scraped_title ? `${r.productUrl} (${r.scraped_title.slice(0, 60)})` : r.productUrl))
    .join(', ');
  out.push({
    json: {
      ...base,
      productUrl: '',
      product_key: '',
      lookup: 'error',
      ok: false,
      code: allFailed ? 'match_failed' : 'no_match',
      error: allFailed
        ? `Pumice product matching failed (${first.match_error}). It will be tried again on the next run.`
        : `None of the top ${list.length} results on ${base.domain} for "${base.searched_for}" matched. Checked: ${checked}. Add the product page in product_url instead.`,
    },
    pairedItem: { item: i },
  });
}

return out;

// Keeps one price check per product page. Rows with a product_url come first,
// then rows found by search, so the first one wins.
const firstRow = new Map();

return $input.all().map((item, i) => {
  const j = item.json;
  if (j.ok === false || !j.product_key) return { json: j, pairedItem: { item: i } };

  if (firstRow.has(j.product_key)) {
    return {
      json: { ...j, ok: false, code: 'duplicate', error: `${j.product_key} is already tracked from row ${firstRow.get(j.product_key)}.` },
      pairedItem: { item: i },
    };
  }
  firstRow.set(j.product_key, j.list_row);
  return { json: j, pairedItem: { item: i } };
});

