// Turns Pumice Smart Scrape's output into a clean price record, and compares it with the
// product's row in the Latest Prices tab to find price changes and stock changes.
const request = $('Remove Duplicate Products').item.json;
const res = $input.item.json;
const settings = $('Settings').first().json;

const fail = (code, error, extra = {}) => ({ json: { ...request, ...extra, ok: false, code, error } });

if (res.error && res.data === undefined && res.result === undefined) {
  const reason = typeof res.error === 'string' ? res.error : res.error?.message;
  return fail('scrape_failed', `Pumice Smart Scrape failed${reason ? ` (${reason})` : ''}. It will be tried again on the next run.`);
}

// The extracted fields can arrive at the top level or nested, as an object or a JSON string
let d = res.data ?? res.result ?? res.output ?? res.extracted ?? res;
if (typeof d === 'string') {
  try { d = JSON.parse(d); } catch (e) { d = {}; }
}
if (Array.isArray(d)) d = d[0] ?? {};
if (d && typeof d === 'object' && d.price === undefined && d.product && typeof d.product === 'object') d = d.product;
d = d ?? {};

const pick = (...keys) => keys.map((k) => d[k]).find((v) => v !== undefined && v !== null && v !== '');

// "$1,299.99", "1.299,99 €" and 1299.99 all become 1299.99
const parsePrice = (value) => {
  if (typeof value === 'number') return Number.isFinite(value) ? value : null;
  let s = String(value ?? '').match(/\d[\d.,]*/)?.[0] ?? '';
  if (!s) return null;
  const lastComma = s.lastIndexOf(',');
  const lastDot = s.lastIndexOf('.');
  if (lastComma > lastDot) {
    s = /,\d{1,2}$/.test(s) ? s.replace(/\./g, '').replace(',', '.') : s.replace(/,/g, '');
  } else if (/^\d{1,3}(\.\d{3})+$/.test(s)) {
    s = s.replace(/\./g, '');
  } else {
    s = s.replace(/,/g, '');
  }
  const n = parseFloat(s);
  return Number.isFinite(n) ? Math.round(n * 100) / 100 : null;
};
const parseNumber = (value) => {
  const n = parseFloat(String(value ?? '').replace(/,/g, '').match(/\d+(\.\d+)?/)?.[0] ?? '');
  return Number.isFinite(n) ? n : null;
};

const price = parsePrice(pick('price', 'current_price', 'sale_price', 'offer_price'));
const title = String(pick('title', 'product_title', 'name') ?? '').trim();
const availability = String(pick('availability', 'availability_text', 'stock') ?? '').trim();

// No price and no title means the page wasn't read
if (price === null && !title) {
  return fail('no_price', 'Pumice could not read a price or title from the page. It will be tried again on the next run.');
}

const scrapedCurrency = String(pick('currency', 'currency_code') ?? '').trim().toUpperCase();
const currency = /^[A-Z]{3}$/.test(scrapedCurrency)
  ? scrapedCurrency
  : (String(settings.default_currency ?? '').trim().toUpperCase() || 'USD');

const listPrice = parsePrice(pick('list_price', 'was_price', 'regular_price', 'original_price', 'compare_at_price'));
const inStockField = pick('in_stock', 'is_in_stock');
let inStock = typeof inStockField === 'boolean'
  ? inStockField
  : /out of stock|sold out|unavailable|discontinued|no longer available|backorder/i.test(availability) ? false
  : /in stock|available|add to cart|ships|only \d+ left|pick up/i.test(availability) ? true
  : null;
// A page with no price is treated as not available to buy
if (price === null && inStock === null) inStock = false;

const money = (n) => {
  try {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency }).format(n);
  } catch (e) {
    return `${currency} ${n.toFixed(2)}`;
  }
};

// Compare with the last check stored in the Latest Prices tab
const last = $('Get Latest Prices').all().map((i) => i.json).find((r) => String(r.product_key ?? '') === request.product_key);
const previous = last ? parsePrice(last.price) : null;
const lowestBefore = last ? parsePrice(last.lowest_price) : null;
const wasInStock = last ? (last.in_stock === 'yes' ? true : last.in_stock === 'no' ? false : null) : null;

const threshold = Math.max(Number(settings.alert_change_percent) || 0, 0);
const priceChange = previous !== null && price !== null ? Math.round((price - previous) * 100) / 100 : null;
const changePercent = priceChange !== null && previous > 0 ? Math.round((priceChange / previous) * 1000) / 10 : null;
const lowest = [lowestBefore, price].filter((n) => n !== null);

const alerts = [];
if (priceChange !== null && priceChange !== 0 && Math.abs(changePercent ?? 0) >= threshold) {
  const direction = priceChange < 0 ? 'Price dropped' : 'Price went up';
  const newLow = priceChange < 0 && lowestBefore !== null && price < lowestBefore ? ', lowest price so far' : '';
  alerts.push(`${direction} ${Math.abs(changePercent)}% from ${money(previous)}${newLow}`);
}
if (previous !== null && price === null) alerts.push('No price on the page');
if (wasInStock === true && inStock === false) alerts.push('Went out of stock');
if (wasInStock === false && inStock === true) alerts.push('Back in stock');

return {
  json: {
    ...request,
    ok: true,
    title,
    url: request.productUrl,
    price,
    price_display: price !== null ? money(price) : 'No price',
    currency,
    previous_price: previous,
    previous_display: previous !== null ? money(previous) : '',
    price_change: priceChange,
    change_percent: changePercent,
    lowest_price: lowest.length ? Math.min(...lowest) : null,
    list_price: listPrice,
    discount_percent: listPrice && price && listPrice > price ? Math.round((1 - price / listPrice) * 100) : null,
    in_stock: inStock,
    availability,
    rating: parseNumber(pick('rating', 'stars', 'average_rating')),
    review_count: parseNumber(pick('review_count', 'reviews', 'ratings_count', 'rating_count')),
    alert: alerts.join('; '),
    checked_at: $now.toFormat('yyyy-MM-dd HH:mm'),
  },
};

// One row per check in the Price History tab
const r = $input.item.json;
return {
  json: {
    checked_at: r.last_checked,
    product_key: r.product_key,
    competitor: r.competitor,
    domain: r.domain,
    sku: r.sku,
    upc: r.upc,
    mpn: r.mpn,
    title: r.title,
    price: r.price,
    currency: r.currency,
    list_price: r.list_price,
    in_stock: r.in_stock,
    url: r.url,
  },
};

// Builds one status update per row of the competitor list, so you can see in the sheet which
// rows need attention. Rows found by search also get the matched page's URL and title,
// so later runs price that page without searching again.
const now = $now.toFormat('yyyy-MM-dd HH:mm');
const rows = new Map();

for (const { json: r } of $input.all()) {
  if (r.list_row === undefined || r.list_row === null || r.list_row === '') continue;
  const s = rows.get(r.list_row) ?? { ok: false, errors: [], notes: [] };
  if (r.ok === true) {
    s.ok = true;
    s.price = r.price ?? '';
    if (r.found_by === 'search') s.matched = { matched_url: r.url, matched_title: r.title };
  } else if (r.code === 'duplicate') {
    s.notes.push(r.error);
  } else {
    s.errors.push(r.error);
  }
  rows.set(r.list_row, s);
}

return [...rows].map(([row, s]) => ({
  json: {
    row_number: row,
    status: s.errors.length ? 'error' : 'ok',
    last_price: s.ok ? s.price : '',
    note: [...new Set([...s.errors, ...s.notes])].join(' | ').slice(0, 1000),
    last_checked: now,
    ...(s.matched ?? {}),
  },
}));

// Builds one email with every competitor price change from this run, grouped by competitor.
// Returns nothing when there are no changes, so no email is sent.
const changes = $input.all().map((i) => i.json).filter((r) => r.ok === true && r.alert);
if (!changes.length) return [];

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const stock = (v) => (v === true ? 'In stock' : v === false ? 'Out of stock' : 'Unknown');
const ids = (r) => [r.sku && `SKU ${r.sku}`, r.upc && `UPC ${r.upc}`, r.mpn && `MPN ${r.mpn}`].filter(Boolean).join(', ');

const byCompetitor = new Map();
for (const r of changes) {
  const name = r.competitor || r.domain;
  if (!byCompetitor.has(name)) byCompetitor.set(name, []);
  byCompetitor.get(name).push(r);
}

const cell = 'style="padding:6px 8px;border-bottom:1px solid #ddd;text-align:left;vertical-align:top"';
let html = `<p>${changes.length} competitor price ${changes.length === 1 ? 'change' : 'changes'} in today's check.</p>`;
for (const [name, list] of byCompetitor) {
  html += `<h3 style="margin:20px 0 6px">${esc(name)}</h3>`;
  html += `<table cellspacing="0" style="border-collapse:collapse;font-size:14px">`;
  html += `<tr><th ${cell}>Product</th><th ${cell}>Change</th><th ${cell}>Price</th><th ${cell}>Previous</th><th ${cell}>Stock</th></tr>`;
  for (const r of list) {
    html += `<tr><td ${cell}><a href="${esc(r.url)}">${esc((r.title || r.product_name || r.url).slice(0, 80))}</a>`
      + `${ids(r) ? `<br><small>${esc(ids(r))}</small>` : ''}</td>`
      + `<td ${cell}><b>${esc(r.alert)}</b></td><td ${cell}>${esc(r.price_display)}</td>`
      + `<td ${cell}>${esc(r.previous_display || 'First check')}</td><td ${cell}>${stock(r.in_stock)}</td></tr>`;
  }
  html += '</table>';
}

const competitors = [...byCompetitor.keys()];
return [{
  json: {
    subject: `Competitor prices: ${changes.length} ${changes.length === 1 ? 'change' : 'changes'} (${competitors.slice(0, 3).join(', ')}${competitors.length > 3 ? ', and more' : ''})`,
    html,
  },
}];

// Reads the API filters from the query string (GET) or JSON body (POST).
// All filters are optional: with none, every tracked product is returned.
const item = $input.item.json;
const req = { ...(item.query ?? {}), ...(item.body && typeof item.body === 'object' ? item.body : {}) };

const list = (value) => (Array.isArray(value) ? value : String(value ?? '').split(','))
  .map((s) => String(s).trim().toLowerCase())
  .filter(Boolean);

const rawDays = String(req.history_days ?? '').trim();
const historyDays = rawDays === '' ? 30 : Number(rawDays);
if (!Number.isInteger(historyDays) || historyDays < 0) {
  return { json: { ok: false, status: 400, code: 'invalid_request', error: 'history_days must be a whole number of days, 0 or more.' } };
}

return {
  json: {
    ok: true,
    competitors: list(req.competitor ?? req.competitors).map((c) => c.replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, '')),
    skus: list(req.sku),
    // Sheets drops the leading zero of a 12-digit UPC stored as a number
    upcs: list(req.upc).map((u) => (/^\d{11}$/.test(u) ? `0${u}` : u)),
    mpns: list(req.mpn),
    history_days: Math.min(historyDays, 365),
  },
};

// Builds the API response from the stored prices: the latest price of each matching competitor
// product, a price comparison per product and per competitor, and each product's price history.
const req = $('Read API Request').first().json;
const reply = (status, body) => [{ json: { status, body } }];

if (!req.ok) return reply(req.status, { ok: false, code: req.code, error: req.error });

const latest = $('Get Latest Prices for API').all().map((i) => i.json);
const sheetError = latest.find((r) => r.error && !r.product_key);
if (sheetError) {
  const reason = typeof sheetError.error === 'string' ? sheetError.error : sheetError.error?.message ?? 'unknown error';
  return reply(500, { ok: false, code: 'sheet_error', error: `Couldn't read the Latest Prices tab (${reason}).` });
}

const stored = latest.filter((r) => r.product_key);
if (!stored.length) {
  return reply(404, {
    ok: false,
    code: 'no_data',
    error: 'No competitor prices are stored yet. Run the daily check once to fill the Latest Prices tab.',
  });
}

const str = (v) => String(v ?? '').trim();
const num = (v) => {
  if (v === '' || v === null || v === undefined) return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};
const bool = (v) => (v === 'yes' || v === true ? true : v === 'no' || v === false ? false : null);
const upc = (v) => (/^\d{11}$/.test(str(v)) ? `0${str(v)}` : str(v));
const has = (wanted, value) => !wanted.length || wanted.includes(value.toLowerCase());

const matches = stored.filter((r) =>
  (!req.competitors.length || req.competitors.includes(str(r.competitor).toLowerCase()) || req.competitors.includes(str(r.domain).toLowerCase())) &&
  has(req.skus, str(r.sku)) && has(req.upcs, upc(r.upc)) && has(req.mpns, str(r.mpn)));

if (!matches.length) {
  return reply(404, {
    ok: false,
    code: 'not_found',
    error: 'No tracked products match these filters.',
    tracked_competitors: [...new Set(stored.map((r) => str(r.competitor)).filter(Boolean))].sort(),
  });
}

// Price history for the matching products, oldest first
const history = new Map();
let historyWarning = null;
if (req.history_days > 0) {
  const cutoff = $now.minus({ days: req.history_days }).toFormat('yyyy-MM-dd HH:mm');
  let rows = [];
  try {
    rows = $('Get Price History for API').all().map((i) => i.json);
  } catch (e) {
    rows = [];
  }
  if (rows.some((r) => r.error && !r.product_key)) historyWarning = "Couldn't read the Price History tab, so history is empty.";
  for (const h of rows) {
    if (!h.product_key || str(h.checked_at) < cutoff) continue;
    if (!history.has(h.product_key)) history.set(h.product_key, []);
    history.get(h.product_key).push({ checked_at: h.checked_at, price: num(h.price), in_stock: bool(h.in_stock) });
  }
  for (const list of history.values()) list.sort((a, b) => str(a.checked_at).localeCompare(str(b.checked_at)));
}

const products = matches
  .map((r) => {
    const p = {
      competitor: str(r.competitor),
      domain: str(r.domain),
      product_name: str(r.product_name),
      sku: str(r.sku),
      upc: upc(r.upc),
      mpn: str(r.mpn),
      title: str(r.title),
      url: str(r.url),
      price: num(r.price),
      currency: str(r.currency),
      previous_price: num(r.previous_price),
      price_change: num(r.price_change),
      change_percent: num(r.change_percent),
      lowest_price: num(r.lowest_price),
      list_price: num(r.list_price),
      discount_percent: num(r.discount_percent),
      in_stock: bool(r.in_stock),
      rating: num(r.rating),
      review_count: num(r.review_count),
      found_by: str(r.found_by),
      alert: r.alert ? str(r.alert) : null,
      last_checked: str(r.last_checked),
    };
    if (req.history_days > 0) p.history = history.get(str(r.product_key)) ?? [];
    return p;
  })
  .sort((a, b) => a.competitor.localeCompare(b.competitor) || a.title.localeCompare(b.title));

// Price ranges are only given when the prices in a group share one currency
const stats = (list) => {
  const priced = list.filter((p) => p.price !== null);
  const currencies = new Set(priced.map((p) => p.currency));
  if (!priced.length || currencies.size !== 1) {
    return { currency: null, lowest_price: null, highest_price: null, average_price: null };
  }
  const prices = priced.map((p) => p.price);
  return {
    currency: [...currencies][0],
    lowest_price: Math.min(...prices),
    highest_price: Math.max(...prices),
    average_price: Math.round((prices.reduce((a, b) => a + b, 0) / prices.length) * 100) / 100,
  };
};
const group = (keyOf) => {
  const groups = new Map();
  for (const p of products) {
    const key = keyOf(p);
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(p);
  }
  return [...groups.values()];
};

// One line per product you track, comparing its price across competitors.
// Rows are grouped by UPC, then MPN, then product name, because SKUs usually differ between stores.
const byProduct = group((p) => (p.upc || p.mpn || p.product_name || p.sku || p.url).toLowerCase()).map((list) => {
  const s = stats(list);
  const cheapest = s.lowest_price !== null ? list.find((p) => p.price === s.lowest_price) : null;
  return {
    product_name: list[0].product_name || list[0].title,
    sku: list[0].sku,
    upc: list[0].upc,
    mpn: list[0].mpn,
    competitors: list.length,
    in_stock: list.filter((p) => p.in_stock === true).length,
    ...s,
    lowest_price_competitor: cheapest ? cheapest.competitor : null,
  };
});

// One line per competitor
const byCompetitor = group((p) => p.competitor).map((list) => ({
  competitor: list[0].competitor,
  products: list.length,
  in_stock: list.filter((p) => p.in_stock === true).length,
  ...stats(list),
}));

const body = {
  ok: true,
  count: products.length,
  as_of: products.map((p) => p.last_checked).sort().pop() ?? null,
  by_product: byProduct,
  by_competitor: byCompetitor,
  products,
};
if (historyWarning) body.warning = historyWarning;

return reply(200, body);
